ProjectALife.DialogueShards["scenes_shelter_4"] = {
{"fw_ld6_shelter_civ_3_0053","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"I said I'd call her back, I was in the middle of a game",2,"The ballgame?",1,"I said gimme a minute, Mom, and I never called her back",3,"She knew..."}},
{"fw_ld6_shelter_civ_3_0054","shelter",2,"reg=civilian,worker|mood=funny",{1,"I read the whole back of the shampoo bottle, it's the most boring thing I've ever read",2,"What's it say?",1,"Lather, rinse, repeat, it's a goddamn trap",2,"You'd be clean forever"}},
{"fw_ld6_shelter_civ_3_0055","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"We should name the bucket",2,"We should not",1,"Gerald, it's a Gerald",3,"Gerald's gonna need emptying"}},
{"fw_ld6_shelter_civ_3_0056","shelter",3,"reg=civilian,worker|mood=angry",{1,"Don't you dare tell me to calm down",2,"I wasn't going to",1,"You had it on your face",3,"Everybody's got it on their face, we've all got it"}},
{"fw_ld6_shelter_civ_3_0057","shelter",3,"reg=civilian,worker|mood=angry|world=building",{1,"Nobody's talking about it, are we gonna just sit here till we die?",2,"Nobody's dying",1,"We're gonna die in this goddamn living room eating Vienna sausages!",3,"Better than dying in the street"}},
{"fw_ld6_shelter_civ_3_0058","shelter",3,"reg=civilian,worker|mood=fear",{1,"Dale's been gone too long, it's been three hours",2,"He said an hour",1,"He said an hour and it's been three, something's wrong, something's wrong",3,"Don't go looking, that's how we lose two"}},
{"fw_ld6_shelter_civ_3_0059","shelter",3,"reg=civilian,family,worker,rescue|mood=funny|world=building",{1,"I haven't slept in so long I just saw a cow in the kitchen",2,"There's no cow",1,"It looked right at me, it had a hat on",3,"Go to sleep, I'll watch the cow"}},
{"fw_ld6_shelter_civ_3_0060","shelter",2,"reg=civilian,worker|mood=angry",{1,"Everybody here smells like a goddamn locker room and nobody's saying it",2,"We're all saying it",1,"Say it louder!"}},
{"fw_ld6_shelter_civ_3_0061","shelter",3,"reg=civilian,family,worker,rescue|mood=fear",{1,"I never minded the dark before. Forty-four years old, and now I... I don't want it dark",2,"You aren't the only one",1,"It's what I can hear in it. That's what gets me",3,"Then light a candle. You don't have to ask us"}},
{"fw_ld6_shelter_civ_3_0062","shelter",3,"reg=civilian,worker|mood=angry",{1,"I don't trust the new guy, he sits too quiet",2,"He's just tired",1,"Nobody's that quiet, he's watching us, he's counting",3,"He's counting the cans, like you, genius"}},
{"fw_ld6_shelter_civ_3_0063","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"I saw a black cat cross the road today",2,"Bad luck",1,"No, it's good luck, it means we're out of bad luck",2,"That's not how luck works"}},
{"fw_ld6_shelter_civ_3_0064","shelter",3,"reg=civilian,worker|mood=sad",{1,"Forty-one years old. I'm not going to sit here crying. I'm not",2,"You don't have to stop on our account",1,"It's dust. In my eye. That's all, it's... dust",3,"Must be the dust, then"}},
{"fw_ld6_shelter_civ_3_0065","shelter",2,"reg=civilian,worker|mood=angry|world=inside",{1,"I'm leaving tomorrow, I'm done with this, I'll take my chances out there",2,"You won't last a day",1,"I'll last longer than you in here, you're not even trying!"}},
{"fw_ld6_shelter_civ_3_0066","shelter",3,"reg=civilian,family,worker,rescue|day=3,10|mood=sad",{1,"What did you do on the first day?",2,"Locked the doors, sat on the bed, held the phone, waited",1,"Same, I held the phone for eight hours, and it never rang",3,"I held mine for three days, and then I put it down"}},
{"fw_ld6_shelter_civ_3_0067","shelter",3,"reg=civilian,worker|mood=funny",{1,"If I live through this I'm never complaining about a goddamn thing again",2,"You'll complain by Christmas",1,"I'll complain about the cold, just the cold, and gladly",3,"I give it six weeks"}},
{"fw_ld6_shelter_civ_3_0068","shelter",2,"reg=civilian,family,worker,rescue|mood=fear",{1,"The kid asked me where Mama is",2,"What did you say?",1,"I said she's resting, she's resting somewhere, and I couldn't look at her"}},
{"fw_ld6_shelter_civ_3_0069","shelter",3,"reg=civilian,worker|mood=funny",{1,"I found a bottle of something in the garage, it's blue",2,"What is it?",1,"I don't know, it's got a skull on it, but it's a nice skull",3,"Put it down, slow, very slow"}},
{"fw_ld6_shelter_civ_3_0070","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"I found a candy bar, an actual candy bar, a Snickers",2,"You're kidding",1,"Cut in four, one for each of us, and nobody say a word",3,"Best Snickers I've ever had, and I haven't even had it yet"}},
{"fw_ld6_shelter_civ_3_0071","shelter",3,"reg=civilian,worker|mood=angry",{1,"If you tell me to pray one more time I'm gonna throw this boot at you",2,"I'm only trying to help",1,"Pray quietly, in your head, like a normal person",3,"Let 'em pray loud, it's how they're wired"}},
{"fw_ld6_shelter_civ_3_0072","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"You ever hear a house sigh?",2,"No",1,"This one does, every so often, like it's tired too",2,"That's the roof cooling..."}},
{"fw_ld6_shelter_civ_3_0073","shelter",2,"reg=civilian,worker|mood=funny",{1,"Anybody got a toothbrush? I'm gonna lose a tooth, it's rotting right out of my head",2,"Use your finger",1,"My finger's disgusting, I just touched a can of corn"}},
{"fw_ld6_shelter_civ_3_0074","shelter",3,"reg=civilian,worker|mood=angry|world=door",{1,"Stop looking at the door like somebody's gonna walk through it",2,"Somebody might",1,"And if they do, you'll look at them like that?",3,"Just look at them like you want to be friends"}},
{"fw_ld6_shelter_civ_3_0075","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"My little brother's nineteen, he's in the Navy, he's somewhere in the Gulf",2,"He'll be fine",1,"He doesn't know any of this, he's probably eating pancakes on a boat",3,"Let him eat pancakes"}},
{"fw_ld6_shelter_civ_3_0076","shelter",2,"reg=civilian,worker|mood=funny",{1,"I'd trade my house for a six-pack and a cold shower",2,"Your house is a dump",1,"It's a dump with a roof, and I'd still trade it"}},
{"fw_ld6_shelter_civ_3_0077","shelter",2,"reg=civilian,family,worker,rescue|day=12,40|mood=sad",{1,"Mom's roses must be dead by now, nobody watering",2,"Maybe it rained",1,"It hasn't rained, I've been watching the sky for two weeks"}},
{"fw_ld6_shelter_civ_3_0078","shelter",3,"reg=civilian,worker|mood=angry",{1,"Why does everybody keep saying 'the infection', it's got a name, hasn't it?",2,"Nobody knows it",1,"Somebody knows it, somebody in a lab knows it",3,"And they're not telling us, that's the damn point"}},
{"fw_ld6_shelter_civ_3_0079","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"I've decided I'm gonna start a farm",2,"A farm?",1,"Chickens, a few goats, I've got a plan, it's a good plan",3,"The first goat's gonna eat the plan"}},
{"fw_ld6_shelter_civ_3_0080","shelter",3,"reg=civilian,worker|x1=m|mood=sad",{1,"I was gonna leave my wife, you know that? Two weeks ago, I had the bag packed",2,"And now?",1,"And now I'd walk to Louisville on my knees to be shouted at by her",3,"Then go find her"}},
{"fw_ld6_shelter_civ_3_0081","shelter",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"You snore, but it's the sound of somebody being alive, so I don't mind",2,"That's the nicest way anyone's ever told me I snore",1,"It's the only way I could say it"}},
{"fw_ld6_shelter_civ_3_0082","shelter",2,"reg=civilian,worker|mood=angry",{1,"Why the hell is it so quiet?",2,"It's night",1,"It's never been this quiet, even at night, even in the middle of nowhere",2,"I know, it's like somebody turned the world down"}},
{"fw_ld6_shelter_civ_3_0083","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"I used to sit on the porch every night, with a cigarette and the crickets",2,"And now?",1,"Now the crickets are the only thing left, and I don't have the cigarette",3,"Wish I could offer the porch back. The cigarette was only part of it"}},
{"fw_ld6_shelter_civ_3_0084","shelter",3,"reg=civilian,worker|day=5,13|mood=funny",{1,"I'd murder for a hot dog from the gas station, the kind that spins",2,"The kind that's been spinning since Tuesday",1,"That's the best kind, they get a crust",3,"I've got a lighter if you wanna spin one"}},
{"fw_ld6_shelter_civ_3_0085","shelter",2,"reg=civilian,worker|mood=angry",{1,"Don't you tell me it's gonna be okay, don't you dare",2,"I wasn't going to",1,"Good, because I'll hit you with this spoon"}},
{"fw_ld6_shelter_civ_3_0086","shelter",3,"reg=civilian,family,worker,rescue|mood=fear",{1,"What if there's nowhere to go?",2,"There's somewhere",1,"What if there isn't? What if it's all like this?",3,"Then we're not gonna find out sitting here"}},
{"fw_ld6_shelter_civ_3_0087","shelter",2,"reg=civilian,worker|mood=sad",{1,"My old man used to say you never know what you've got till it's gone, and I thought he was full of shit",2,"He was",1,"He was full of shit and he was right, that's the worst part"}},
{"fw_ld6_shelter_civ_3_0088","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Nicest house I ever slept in, I couldn't enjoy it",2,"Too worried?",1,"Had a bathtub with feet. Nearly cried looking at it",3,"I'd have cried too. Nice things can make you miss your own place worse"}},
{"fw_ld6_shelter_civ_3_0089","shelter",3,"reg=civilian,worker|hour=16,5|mood=funny",{1,"I almost shot a cat tonight, Jesus Christ, I thought it was a person",2,"You're getting jumpy",1,"I'm getting accurate, I almost hit it",3,"Don't shoot cats, they're the last smart things we've got"}},
{"fw_ld6_shelter_civ_3_0090","shelter",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"We should make a list of everybody's favorite things, when this is over, we'll do them all",2,"A list of what?",1,"Favorite foods, favorite songs, favorite places, I'll start",2,"Start with the foods"}},
{"fw_ld6_shelter_civ_3_0091","shelter",3,"reg=civilian,worker|mood=angry",{1,"Somebody ate the last of the crackers and left the wrapper in the can",2,"That's disgusting",1,"It's more than disgusting, it's a message!",3,"It's a cracker wrapper, calm down"}},
{"fw_ld6_shelter_civ_3_0092","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"It's weird, I miss the news, even the bad news",2,"Me too",1,"The weatherman, the man who reads the school closings",3,"The man with the farm report"}},
{"fw_ld6_shelter_civ_3_0093","shelter",2,"reg=civilian,worker|mood=fear",{1,"I keep dreaming about my mother's kitchen, the light's on, and she's got her back to me",2,"What does she say?",1,"She never turns around, I just stand there"}},
{"fw_ld6_shelter_civ_3_0094","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Let's play a game, whoever says 'when this is over' pays a can",2,"We don't have cans to pay",1,"That's the genius, nobody can pay, and nobody can say it",3,"You just said it"}},
{"fw_ld6_shelter_civ_3_0095","shelter",2,"reg=civilian,worker|mood=angry",{1,"If I hear one more joke about the damn beans I'm gonna eat the cook",2,"That's cannibalism",1,"That's justice"}},
{"fw_ld6_shelter_civ_3_0096","shelter",3,"reg=civilian,worker|mood=angry",{1,"Goddamn flies, they're all over the food, I'm gonna lose my fuckin'--",2,"Wave a rag at 'em",1,"I AM waving a rag, they just land on the rag!",3,"Then eat in the other room"}},
{"fw_ld6_shelter_civ_3_0097","shelter",2,"reg=civilian,family,worker,rescue|mood=fear",{1,"I can't believe this is happening, it's like a bad dream, I keep waiting to wake up and it's Friday morning",2,"Me too",1,"And then I smell it, and I know I'm awake"}},
{"fw_ld6_shelter_civ_3_0098","shelter",3,"reg=civilian,worker|mood=angry|world=building",{1,"Do you hear that? Shh-- no, wait, nothing, never mind",2,"You've done that nine times",1,"I'm sorry, I'm sorry, I can't turn it off!",3,"Then go sit by the wall and be quiet"}},
{"fw_ld6_shelter_civ_3_0099","shelter",3,"reg=civilian,family,worker,rescue|mood=angry",{1,"Nobody told me it'd be like this, the TV said stay calm, stay calm, and I'm sitting here SHAKING",2,"I know",1,"Stay calm, they said, stay in your homes, and I did, and look!",3,"Look at what? We're alive"}},
{"fw_ld6_shelter_civ_3_0100","shelter",2,"reg=civilian,worker|mood=angry",{1,"Why the hell didn't we leave Thursday? I told you, I TOLD you, the radio said--",2,"The radio said a lot of things",1,"It said leave, and you said it's a drill!"}},
{"fw_ld6_shelter_civ_3_0101","shelter",3,"reg=civilian,family,worker,rescue|mood=fear",{1,"Shut up, shut up, just shut up a second, I'm trying to remember something",2,"What?",1,"It's gone now, it was important, it was my sister's phone number",3,"It'll come back, don't force it"}},
{"fw_ld6_shelter_civ_3_0102","shelter",2,"reg=civilian,worker|mood=sad",{1,"I'm not crying, it's the, it's the-- fuck, it's just crying, okay, I'm crying",2,"Nobody's looking",1,"Look away anyway!"}},
{"fw_ld6_shelter_civ_3_0103","shelter",3,"reg=civilian,family,worker,rescue|mood=angry",{1,"Why does everything smell like feet?!",2,"It's all of us",1,"It's all of us AND the house, the house smells like feet and a dead mouse",3,"It's mostly the dead mouse"}},
{"fw_ld6_shelter_civ_3_0104","shelter",2,"reg=civilian,worker|mood=funny",{1,"If you see me turn, shoot me in the head and take my boots",2,"Deal",1,"And don't wear them in front of my mother, she'd kill you",2,"She'd have to get in line"}},
{"fw_ld6_shelter_civ_3_0105","shelter",3,"reg=civilian,family,worker,rescue|mood=fear",{1,"Swear to God I heard a car, an engine, a real one-- hold on",2,"Where?",1,"Gone, it's gone, swear to-- no, I mean, I'm sure",3,"You said 'swear to God' twice, calm down"}},
{"fw_ld6_shelter_civ_3_0106","shelter",3,"reg=civilian,worker|mood=angry",{1,"If one more person tells me to 'stay positive' I'll scream, I'll fuckin' SCREAM",2,"Stay positive",1,"I'm warning you!",3,"Positive's all we've got"}},
{"fw_ld6_shelter_civ_3_0107","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"I keep patting my pocket for my phone, and then I remember, and it's like losing it all over again",2,"Which phone?",1,"Any phone, the one in the kitchen, the one at work, all of them",3,"Me too, every time"}},
{"fw_ld6_shelter_civ_3_0108","shelter",2,"reg=civilian,worker|mood=angry",{1,"Who the fuck cooks beans in a pot without a lid and leaves the spoon in?!",2,"I was gonna come back",1,"You're always gonna come back!"}},
{"fw_ld6_shelter_civ_3_0109","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"If I turn into one of those things I'm going to bite the guy who woke me up first",2,"That's fair",1,"Starting with whoever's breathing like that",3,"That's me, go ahead"}},
{"fw_ld6_shelter_civ_3_0110","shelter",2,"reg=civilian,worker|mood=fear",{1,"They could be right outside, right now, standing there, and we wouldn't even know",2,"Stop it",1,"I'm just SAYING, we're sitting here with the lights off like it's a movie!"}},
{"fw_ld6_shelter_civ_3_0111","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"I wish I'd called more, you know? I wish I'd just called, just to say nothing",2,"We all wish that",1,"I had nothing to say, and I'd say it for an hour, God",3,"I'd listen to your nothing"}},
{"fw_ld6_shelter_civ_3_0112","shelter",2,"reg=civilian,worker|mood=angry",{1,"You think you're better than me because you've got a gun?",2,"I didn't say that",1,"You looked it!"}},
{"fw_ld6_shelter_civ_3_0113","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"I haven't had a cup of coffee in nine days and I think I can see through time",2,"What's it look like?",1,"Gray, mostly, and a bit of Tuesday",3,"Get the man a cup of something"}},
{"fw_ld6_shelter_civ_3_0114","shelter",3,"reg=civilian,worker|mood=angry",{1,"Goddammit, the lantern's out, who touched the lantern?",2,"Nobody",1,"Nobody touched it, it just turned itself off, great, FANTASTIC",3,"It's out of oil, you dumbass"}},
{"fw_ld6_shelter_civ_3_0115","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"My hands smell like the bleach I used on the kitchen floor Friday, and I can't get it off",2,"Wash them",1,"I washed them, it doesn't go, it's like a-- like a stain on my brain"}},
{"fw_ld6_shelter_civ_3_0116","shelter",3,"reg=civilian,worker|mood=funny",{1,"I'm so goddamn tired I just said 'thank you' to a chair",2,"Did it say you're welcome?",1,"It kind of creaked",3,"Good manners"}},
{"fw_ld6_shelter_civ_3_0117","shelter",3,"reg=civilian,family,worker,rescue|mood=fear",{1,"What do you do if you see one up close?",2,"Don't look at it",1,"I'm asking what I DO",3,"Walk away, slow, and don't turn around"}},
{"fw_ld6_shelter_civ_3_0118","shelter",2,"reg=civilian,worker|mood=angry",{1,"It's been eight days and nobody's coming! Eight! I counted! It's eight!",2,"I know, I know it's eight",1,"Then why are we still sitting here!"}},
{"fw_ld6_shelter_civ_3_0119","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"I'm just saying, thank you, for not leaving me",2,"I wasn't going to",1,"I know, but thank you, I wanted to say it before I lost my nerve",3,"That was a lot of words for you"}},
{"fw_ld6_shelter_civ_3_0120","shelter",3,"reg=civilian,worker|mood=angry",{1,"Quit tapping your foot, it's driving me up the goddamn wall",2,"I'm not tapping",1,"Your whole leg is going like a sewing machine!",3,"Both of you, outside"}},
{"fw_ld6_shelter_civ_3_0121","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"I would give anything for a decent cup of black coffee and a Marlboro Light",2,"And a newspaper",1,"And a newspaper, and my mother's meatloaf",2,"You'd forgive her anything for that meatloaf"}},
{"fw_ld6_shelter_civ_3_0122","shelter",3,"reg=civilian,worker|mood=sad",{1,"I used to be a good person, I did, I coached Little League",2,"You're still a good person",1,"I stepped over a man on the road, I looked right at him, and I stepped over him",3,"You did what you had to..."}},
{"fw_ld6_shelter_civ_3_0123","shelter",2,"reg=civilian,family,worker,rescue|mood=fear|world=door,inside",{1,"I can't breathe in here, I need the door open, please, just a crack",2,"You know we can't",1,"Just a crack, I'm gonna pass out, I'm gonna-- okay, okay, I'm okay"}},
{"fw_ld6_shelter_civ_3_0124","shelter",3,"reg=civilian,worker|mood=angry|world=building",{1,"I told you not to sit on the couch, it's got a stain on it, God knows what it is",2,"It's a couch",1,"It's a goddamn crime scene!",3,"It's coffee, from before, I saw them spill it"}},
{"fw_ld6_shelter_civ_3_0125","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"We've been eating the same thing for eight days and I am BEGINNING to hate beans",2,"Beginning?",1,"I'm beginning to hate them in a new way, a more personal way",3,"They hate you back"}},
{"fw_ld6_shelter_civ_3_0126","shelter",2,"reg=civilian,worker|mood=angry",{1,"Don't you dare use the good bucket for that",2,"It's a bucket",1,"It's THE good bucket, it's got a handle!"}},
{"fw_ld6_shelter_civ_3_0127","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"There was a lady at the Piggly Wiggly who always gave me the extra coupon, and I never thanked her",2,"The one with the red glasses?",1,"The red glasses, yes, and I never even learned her name",3,"Her name was Dolores"}},
{"fw_ld6_shelter_civ_3_0128","shelter",2,"reg=civilian,worker|mood=funny",{1,"If the world ends and I'm still stuck with you, I want it on record, I didn't pick this",2,"Noted",1,"Write it down, I want a lawyer"}},
{"fw_ld6_shelter_civ_3_0129","shelter",3,"reg=civilian,family,worker,rescue|mood=fear|world=window",{1,"I thought I saw somebody in the window, I did-- no, I mean, I thought, it was probably the curtain",2,"It's a curtain",1,"It had a hat",3,"Don't look at the window anymore"}},
{"fw_ld6_shelter_civ_3_0130","shelter",2,"reg=civilian,worker|mood=angry",{1,"Everybody needs to stop being nice, the nice is gonna get us killed",2,"We're not being nice",1,"You offered the guy a SANDWICH, I saw you!"}},
{"fw_ld6_shelter_civ_3_0131","shelter",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"You know what? I like you, I didn't think I would, but I do",2,"That's the nicest thing anybody said to me this week",1,"Don't let it go to your head"}},
{"fw_ld6_shelter_civ_3_0132","shelter",3,"reg=civilian,worker|mood=funny",{1,"I've been thinking, if I get out of this alive I'm gonna quit my job and open a fuckin' bait shop",2,"You hate fish",1,"I don't hate fish, I hate fishermen, they'd be the customers",3,"Bait shop and a hot dog stand, that's the plan"}},
{"fw_ld6_shelter_civ_3_0133","shelter",4,"reg=civilian,family,worker,rescue|mood=angry",{1,"You said you'd teach me gin rummy",2,"I'm teaching you",1,"You're winning, that's not teaching",3,"That's how I learned",2,"That's how everybody learned",4,"Quit whining, both of you, I'm trying to hear the road"}},
{"fw_ld6_shelter_civ_3_0134","shelter",4,"reg=civilian,family,worker,rescue|mood=funny",{1,"Whose deal is it?",2,"Yours",1,"I dealt last",3,"Nobody's dealt in an hour, you're both stalling",4,"Nothing out there, if anybody cares"}},
{"fw_ld6_shelter_civ_3_0135","shelter",4,"reg=civilian,family,worker,rescue|mood=funny",{1,"Would you trade socks for a cigarette?",2,"What kind of cigarette?",1,"Any kind, apparently",3,"Not if the socks smelled like a barn",2,"My socks don't smell like a barn",4,"No. Yours smell like a barn that burned down"}},
{"fw_ld6_shelter_civ_3_0136","shelter",4,"reg=civilian,family,worker,rescue|day=2,13|mood=sad",{1,"Where's Dale?",2,"Asleep, in the back",1,"He's been asleep since noon",3,"Leave him, he didn't sleep Saturday either",4,"He doesn't sleep, he lies there with his eyes open"}},
{"fw_ld6_shelter_civ_3_0137","shelter",4,"reg=civilian,family,worker,rescue|mood=funny",{1,"Eleven cans of beans",2,"I count nine",1,"Eleven, I counted twice",3,"It's nine and two empties",4,"Nine, I held every one"}},
{"fw_ld6_shelter_civ_3_0138","shelter",4,"reg=civilian,family,worker,rescue|mood=calm",{1,"Move the dial a hair to the left",2,"This way?",1,"The other left",3,"You've got it, you've got a station",4,"That's a preacher, go back, go back"}},
